package com.aac.ieojwo.location.controller;
import com.aac.ieojwo.common.api.ApiResponse;import com.aac.ieojwo.location.service.LocationService;import com.aac.ieojwo.location.service.LocationService.*;import org.springframework.http.HttpStatus;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.web.bind.annotation.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/api/v1/me/aac-users/{userId}")
public class LocationController{private final LocationService service;public LocationController(LocationService s){service=s;}@GetMapping("/places")public ApiResponse<List<PlaceResponse>> places(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId){return ApiResponse.ok(service.places(p,userId));}@PostMapping("/places")@ResponseStatus(HttpStatus.CREATED)public ApiResponse<PlaceResponse> create(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@RequestBody PlaceRequest r){return ApiResponse.ok(service.save(p,userId,null,r));}@PutMapping("/places/{placeId}")public ApiResponse<PlaceResponse> update(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@PathVariable Long placeId,@RequestBody PlaceRequest r){return ApiResponse.ok(service.save(p,userId,placeId,r));}@DeleteMapping("/places/{placeId}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@PathVariable Long placeId){service.delete(p,userId,placeId);}@GetMapping("/locations/latest")public ApiResponse<LocationResponse> latest(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId){return ApiResponse.ok(service.latest(p,userId));}@GetMapping("/locations")public ApiResponse<List<LocationResponse>> history(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@RequestParam Instant from,@RequestParam Instant to){return ApiResponse.ok(service.history(p,userId,from,to));}}
